function mergeInto(a: number[], m: number, b: number[], n: number): void {
  let i = m - 1, j = n - 1, w = m + n - 1;
  while (j >= 0) {
    if (i >= 0 && a[i] > b[j]) a[w--] = a[i--];
    else a[w--] = b[j--];
  }
}

