class Solution:
    def mergeInto(self, a: List[int], m: int, b: List[int], n: int) -> None:
        i, j, w = m - 1, n - 1, m + n - 1
        while j >= 0:
            if i >= 0 and a[i] > b[j]:
                a[w] = a[i]
                i -= 1
            else:
                a[w] = b[j]
                j -= 1
            w -= 1

